const fs=require('fs');let s=fs.readFileSync('system.ts','utf8');
const blk=(me,other)=>`require($.${me} === $.assigned, 'task-already-reported'),
          set('${me}', $.outcome),
          when($.${other} === $.completed, [set('status', $.outcome)]),
          when($.${other} === $.failed, [set('status', $.failed)]),
          when($.${other} === $.cancelled, [
            when($.outcome === $.failed, [set('status', $.failed)], [set('status', $.cancelled)]),
          ]),`;
s=s.replace(/when\(\$\.task === 0, \[[\s\S]*?\], \[\s*require[\s\S]*?\]\),\n        \]\),/, `when($.task === 0, [
          ${blk('task0','task1')}
        ], [
          ${blk('task1','task0')}
        ]),`);
s=s.replace("outcome: t.named('Outcome')","outcome: t.named('TaskStatus').check([name('completed'), name('failed'), name('cancelled')])");
s=s.replace("  enumType('Outcome', ['completed', 'failed', 'cancelled']),\n","");
s=s.replace("configuration, instance, implies,","configuration, instance, implies, name,");
fs.writeFileSync('system.ts',s);
EOF
sed -n 40,70p system.ts; cd ..; npx tsc --noEmit -p tsconfig.json; npm run poly -- check src/system.ts

