import { test } from 'node:test';
import assert from 'node:assert/strict';
import create from '../build/host.gen.ts';

const view = (status: string, task0: string, task1: string, retried0 = false, retried1 = false) =>
  ({ status, task0, task1, retried0, retried1 });

test('fresh system is idle', async () => {
  const h = await create();
  assert.deepEqual(await h.run(), view('idle', 'idle', 'idle'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nobody'), null);
  assert.equal((await h.workDone('worker0')).ok, false);
  assert.equal((await h.cancel()).ok, false);
});

test('start sends Assign to both; both complete', async () => {
  const h = await create();
  assert.deepEqual(await h.start(), { ok: true });
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned'));
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action]).sort(), [['run', 'worker0', 'Assign'], ['run', 'worker1', 'Assign']]);
  assert.equal((await h.start()).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0'), { ok: true });
  const r = await h.inFlight();
  assert.equal(r.length, 1);
  assert.deepEqual([r[0].from, r[0].to, r[0].action, r[0].data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'completed', 'assigned'));
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed'));
});

test('first failure is retried; second failure is recorded', async () => {
  const h = await create();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1');
  const [rep] = await h.inFlight();
  await h.deliver(rep.id);
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned', false, true));
  assert.deepEqual((await h.inFlight()).map((m) => [m.from, m.to, m.action]), [['run', 'worker1', 'Assign']]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workFailed('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'assigned', 'failed', false, true));
  await h.workDone('worker0'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'completed', 'failed', false, true));
});

test('retry then success completes the run', async () => {
  const h = await create();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0'); await h.deliverAll();
  await h.workDone('worker0'); await h.workDone('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', true, false));
});

test('cancel aborts only assigned tasks', async () => {
  const h = await create();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0'); await h.deliverAll();
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.cancel()).ok, false);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.to, m.action]), [['worker1', 'Abort']]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('cancelled', 'completed', 'cancelled'));
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

test('failure while cancelling is not retried', async () => {
  const h = await create();
  await h.start(); await h.deliverAll();
  await h.cancel();
  assert.equal((await h.run()).status, 'cancelling');
  await h.workDone('worker0');
  await h.workFailed('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'completed', 'failed'));
});

test('cancel before Assign delivered', async () => {
  const h = await create();
  await h.start();
  await h.cancel();
  for (const m of (await h.inFlight()).filter((m) => m.action === 'Abort')) await h.deliver(m.id);
  assert.equal((await h.run()).status, 'cancelling');
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
});

