import { test } from 'node:test';
import assert from 'node:assert/strict';
import create from '../build/host.gen.ts';

const view = (status: string, task0: string, task1: string, retried0 = false, retried1 = false, processed = 0) =>
  ({ status, task0, task1, retried0, retried1, processed });

test('fresh system is idle', async () => {
  const h = await create();
  assert.deepEqual(await h.run(), view('idle', 'idle', 'idle'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nobody'), null);
  assert.equal((await h.workDone('worker0', 1)).ok, false);
  assert.equal((await h.cancel()).ok, false);
});

test('start sends Assign to both; both complete', async () => {
  const h = await create();
  assert.deepEqual(await h.start(), { ok: true });
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned'));
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action]).sort(), [['run', 'worker0', 'Assign'], ['run', 'worker1', 'Assign']]);
  assert.equal((await h.start()).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0', 2), { ok: true });
  const r = await h.inFlight();
  assert.equal(r.length, 1);
  assert.deepEqual([r[0].from, r[0].to, r[0].action, r[0].data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed', items: 2 }]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'completed', 'assigned', false, false, 2));
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', false, false, 3));
});

test('workDone refuses items other than 1 or 2', async () => {
  const h = await create();
  await h.start(); await h.deliverAll();
  for (const n of [0, 3, -1, 1.5]) {
    const o = await h.workDone('worker0', n);
    assert.equal(o.ok, false, `items ${n}`);
  }
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.deepEqual(await h.inFlight(), []);
});

test('first failure is retried; second failure is recorded', async () => {
  const h = await create();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1');
  const [rep] = await h.inFlight();
  assert.deepEqual(rep.data, { task: 1, outcome: 'failed', items: 0 });
